{
    public static string Language { get; private set; } = "pt";
    public static readonly string[] Languages = { "pt", "en", "es" };
    public static readonly string[] LanguageNames = { "Português", "English", "Español" };
    public static void Use(string language) => Language = Languages.Contains(language) ? language : "en";
    public static string T(string text) => In(Language, text);
    public static string In(string language, string text) => language != "pt" && messages.TryGetValue(text, out var value)
        ? language == "es" ? value.Es : value.En : text;
    public static string F(string format, params object[] args) => string.Format(CultureInfo.InvariantCulture, T(format), args);
    public static string Date(DateTime value) => value.ToString(Language == "en" ? "yyyy-MM-dd HH:mm 'UTC'" : "dd/MM/yyyy HH:mm 'UTC'", CultureInfo.InvariantCulture);
    public static IReadOnlyCollection<string> Keys => messages.Keys;

    // Only labels introduced by CertBox are translated. Certificate identities,
    // OIDs, URLs and raw extension content retain their original values.
    public static string Detail(string value) => value
        .Replace(" · Crítica", " · " + T("Crítica"), StringComparison.Ordinal)
        .Replace("Identificador: ", T("Identificador") + ": ", StringComparison.Ordinal)
        .Replace("Nome alternativo (tipo ", T("Nome alternativo (tipo") + " ", StringComparison.Ordinal);

